package app.loveu;

import android.app.*;import android.content.*;import android.content.res.Configuration;import android.os.LocaleList;import android.widget.*;
import org.json.*;import java.util.*;import java.util.regex.*;import java.io.*;import java.nio.charset.StandardCharsets;

/** Offline presentation only. Canonical record values and private text never change. */
final class Language {
 static final String[] CODES={"system","zh-Hans","zh-Hant","en","ja","ko","es","fr","de","pt"};
 static final String[] NAMES={"跟随系统 / System","简体中文","繁體中文","English","日本語","한국어","Español","Français","Deutsch","Português"};
 static String code="zh-Hans";static Map<String,String> dictionary=Collections.emptyMap();static List<String> keys=Collections.emptyList();static List<Template> templates=Collections.emptyList();
 static final Pattern RAW=Pattern.compile("\uE000([A-Za-z0-9+/=]*)\uE001");
 static final class Template{final Pattern pattern;final String value;Template(String key,String value){StringBuilder regex=new StringBuilder("^");Matcher m=Pattern.compile("\\{(\\d+)\\}").matcher(key);int at=0;while(m.find()){regex.append(Pattern.quote(key.substring(at,m.start()))).append("(.+?)");at=m.end();}regex.append(Pattern.quote(key.substring(at))).append('$');pattern=Pattern.compile(regex.toString(),Pattern.DOTALL);this.value=value;}}
 static String preference(Context c){return c.getSharedPreferences("loveu_language",Context.MODE_PRIVATE).getString("language","system");}
 static String resolve(String requested,Locale system){if(!"system".equals(requested)&&Arrays.asList(CODES).contains(requested))return requested;String language=system.getLanguage();if(language.equals("zh"))return system.getScript().equals("Hant")||Arrays.asList("TW","HK","MO").contains(system.getCountry())?"zh-Hant":"zh-Hans";return Arrays.asList(CODES).contains(language)?language:"en";}
 static synchronized void load(Context context){String selected=resolve(preference(context),android.content.res.Resources.getSystem().getConfiguration().getLocales().get(0));code=selected;Map<String,String> data=new HashMap<>();List<Template> rules=new ArrayList<>();if(!code.equals("zh-Hans"))try(InputStream in=context.getAssets().open("i18n/"+code+".json")){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1)bytes.write(buffer,0,n);JSONObject json=new JSONObject(new String(bytes.toByteArray(),StandardCharsets.UTF_8));Iterator<String> names=json.keys();while(names.hasNext()){String key=names.next();data.put(key,json.getString(key));}List<String> ordered=new ArrayList<>(data.keySet());ordered.sort((a,b)->Integer.compare(b.replaceAll("\\{\\d+\\}","").length(),a.replaceAll("\\{\\d+\\}","").length()));for(String key:ordered)if(key.contains("{0}")&&key.replaceAll("[^\\u3400-\\u9fff]","").length()>=2)rules.add(new Template(key,data.get(key)));}catch(Exception failure){throw new IllegalStateException("Language pack unavailable: "+code,failure);}List<String> ordered=new ArrayList<>(data.keySet());ordered.removeIf(k->k.isEmpty()||k.contains("{0}")||(!k.equals(k.trim())&&k.trim().length()<=2));ordered.sort((a,b)->Integer.compare(b.length(),a.length()));dictionary=Collections.unmodifiableMap(data);keys=Collections.unmodifiableList(ordered);templates=Collections.unmodifiableList(rules);}
 static Context wrap(Context base){load(base);Configuration c=new Configuration(base.getResources().getConfiguration());c.setLocales(new LocaleList(Locale.forLanguageTag(code)));return base.createConfigurationContext(c);}
 static String raw(String text){return "\uE000"+java.util.Base64.getEncoder().encodeToString((text==null?"":text).getBytes(StandardCharsets.UTF_8))+"\uE001";}
 static String restore(String text){Matcher m=RAW.matcher(text);StringBuffer out=new StringBuffer();while(m.find())m.appendReplacement(out,Matcher.quoteReplacement(new String(java.util.Base64.getDecoder().decode(m.group(1)),StandardCharsets.UTF_8)));m.appendTail(out);return out.toString();}
 static String ui(CharSequence value){return value==null?"":restore(translate(value.toString(),0));}
 static String translate(String value,int depth){if(code.equals("zh-Hans")||value.isEmpty())return value;boolean chinese=false;for(int n=0;n<value.length();n++)if(value.charAt(n)>=0x3400&&value.charAt(n)<=0x9fff){chinese=true;break;}if(!chinese)return value;if(RAW.matcher(value).matches())return value;String direct=dictionary.get(value);if(direct!=null)return direct;
  if(depth<2)for(Template template:templates){Matcher m=template.pattern.matcher(value);if(m.matches()){String result=template.value;for(int i=m.groupCount()-1;i>=0;i--)result=result.replace("{"+i+"}",translate(m.group(i+1),depth+1));return result;}}
  StringBuilder out=new StringBuilder();for(int i=0;i<value.length();){if(value.charAt(i)=='\uE000'){int end=value.indexOf('\uE001',i);if(end>=0){out.append(value,i,end+1);i=end+1;continue;}}String matched=null;for(String key:keys)if(value.startsWith(key,i)){matched=key;break;}if(matched!=null){String part=dictionary.get(matched);if(latin()&&out.length()>0&&Character.isLetterOrDigit(out.charAt(out.length()-1))&&!part.isEmpty()&&Character.isLetterOrDigit(part.charAt(0)))out.append(' ');out.append(part);i+=matched.length();if(latin()&&i<value.length()&&Character.isLetterOrDigit(value.charAt(i))&&!part.isEmpty()&&Character.isLetterOrDigit(part.charAt(part.length()-1)))out.append(' ');}else out.append(value.charAt(i++));}return out.toString();
 }
 static boolean latin(){return Arrays.asList("en","es","fr","de","pt").contains(code);}
 static String[] rawItems(String[] input){String[] out=new String[input.length];for(int i=0;i<input.length;i++)out[i]=raw(input[i]);return out;}
 static CharSequence[] items(CharSequence[] input){if(input==null)return null;CharSequence[] out=new CharSequence[input.length];for(int i=0;i<input.length;i++)out[i]=ui(input[i]);return out;}
 static String source(TextView view){return view instanceof LanguageViews.Source?((LanguageViews.Source)view).source():view.getText().toString();}
 static String shortDate(java.time.LocalDate date){Locale locale=Locale.forLanguageTag(code);String pattern=android.text.format.DateFormat.getBestDateTimePattern(locale,"MMMd");return date.format(java.time.format.DateTimeFormatter.ofPattern(pattern,locale));}
 static String[] weekdays(){java.text.DateFormatSymbols d=new java.text.DateFormatSymbols(Locale.forLanguageTag(code));String[] names=d.getShortWeekdays(),out=new String[7];for(int i=0;i<7;i++)out[i]=names[i+1];return out;}
 static String name(Context c){String selected=preference(c);for(int i=0;i<CODES.length;i++)if(CODES[i].equals(selected))return i==0?NAMES[i]:raw(NAMES[i]);return NAMES[0];}
 static void choose(MainActivity a){String selected=preference(a);int index=Arrays.asList(CODES).indexOf(selected);String[] names=rawItems(NAMES);names[0]=NAMES[0];AlertDialog dialog=new LanguageDialog(a).setTitle("语言 / Language").setSingleChoiceItems(names,Math.max(0,index),(d,i)->{d.dismiss();select(a,CODES[i]);}).setNegativeButton("取消",null).create();a.dialogs.add(dialog);dialog.show();if(a.workbuddy())WorkbuddyUi.decorate(dialog);}
 static void select(MainActivity a,String selected){if(!Arrays.asList(CODES).contains(selected))throw new IllegalArgumentException("Unsupported language");a.getSharedPreferences("loveu_language",Context.MODE_PRIVATE).edit().putString("language",selected).commit();load(a);Configuration c=new Configuration(a.getResources().getConfiguration());c.setLocales(new LocaleList(Locale.forLanguageTag(code)));a.getResources().updateConfiguration(c,a.getResources().getDisplayMetrics());a.closeCouple();a.workbuddyInsights=null;a.workbuddyPeriod=null;a.insights=null;a.workbuddyPage="";a.workbuddyBack.clear();a.tab="我的";a.show();}
}
